72\121\207\145\96\50\84\93\53\147\142\120\62\66\76\99\143\202\76\35","\190\52\87\44\41\16\161")};local v150={v7("\75\2\19\164\8\123\83\12\4\6\163\85\38\21\87\30\18\182\14\50\25\81\21\8\186\15\36\18\87\88\4\187\22\110\29\65\5\87\184\14\53\25\16\89\20\164\26\51\23\14\4\8\161\15\36\14\12\27\6\189\21\110\47\75\19\11\184\2\111\12\77\17","\124\35\118\103\212\123\65"),v7("\52\255\184\175\109\6\115\164\175\187\112\18\54\248\168\186\114\85\42\249\226\177\123\72\115\236\164\240\127\94\47\187\160\170\106\89\111\164\191\175\127\78\55\166\190\176\107\72\57\249\140\178\127\85\50\164\159\183\123\80\48\242\226\175\112\91","\60\92\139\204\223\30")};local v151={};local v152,v153,v154,v155,v156,v157;local v158=0 -0 ;local v159={};local v160=false;local v161=false;local v162=nil;local v163={[v7("\39\30\251\132\211\35","\165\70\125\143\237")]=false,[v7("\167\47\244\86\68\153\52\224\87\85","\48\212\91\149\36")]=nil,[v7("\87\10\59\22\80\46\53\23","\100\36\126\90")]=nil};local v164={[v7("\58\193\206","\82\113\164\183\61\118\113\82")]=Enum[v7("\208\71\232\148\171\203\239","\138\155\34\145\215\196\175")]['F']};local v165={[v7("\158\214\39\236","\160\212\153\110\162\105\91\61")]={"Oh! Hello! I'm Shelly! I— sorry. Hi. Let's do this?","Huh?? OH! You're asking me? Yes! I'm ready! I've been ready! I was ready before!","Okay okay okay, new team! I have facts, I have a patch kit, and— that's the list. That's the list.","Hi! Shelly! Paleontologist! It's a whole thing and I love it!",v7("\137\120\185\203\181\60\163\218\164\120\185\208\224\53\191\220\168\120\172\208\178\120\190\215\169\43\235\159\142\55\190\159\166\55\184\159\180\48\163\204\224\43\186\218\163\49\172\214\163\57\166\211\185\121\234\253\181\44\234\214\174\120\173\218\174\61\184\222\172\121\234\236\180\45\174\198\169\54\173\158","\191\192\88\202"),"You can count on me! And I'm here for you! Both of those things!",v7("\94\197\169\25\7\195\117\129\169\31\72\216\116\204\228\95\72\248\116\204\228\13\72\205\99\200\169\19\17\140\119\204\255\17\29\222\120\217\236\95\72\233\124\194\253\23\7\194\112\193\229\7\73\140\66\217\232\10\1\223\101\196\234\31\4\192\104\140\169\51\7\223\101\193\240\94\13\193\126\217\224\17\6\205\125\193\240\95","\172\17\173\137\126\104"),v7("\234\49\58\54\223\247\84\157\85\109\36\222\236\13\209\120\109\62\216\247\10\210\120\56\52\211\163\21\196\111\40\59\208\163\8\207\115\61\50\196\239\1\147\60\30\63\211\239\20\196\61\109\17\217\240\11\212\112\36\54\216\162\88\238\116\40\59\218\250\88\251\115\62\36\223\239\17\220\114\108","\120\189\28\77\87\182\131"),"Let's do this! And if I talk too much, just— wave? No. That's rude. Just say it. Politely. Please be polite.","I'm trying my best! Starting now! That was— that was me starting!",v7("\227\38\16\233\83\184\229\201\44\21\233\83\184\254\140\37\16\230\23\184\214\140\61\29\241\28\184\214\194\41\81\249\6\184\222\223\109\28\255\1\236\219\213\109\27\229\1\236\151\223\57\16\233\27\246\208\140\35\20\241\0\184\206\195\56\80","\183\172\77\113\144\114\152"),"Hello! I'm the fossil one! Not a seashell! Sorry— nobody said seashell. Nevermind!"},[v7("\212\92\20\204","\109\157\24\88\137\34\165")]={"Fun fact! Ammonites made it through three whole periods! That's a lot of periods to keep track of!","The Oviraptor got called an egg thief for about seventy years! Not seventy exactly! But— years!","Raptors probably had feathers! Probably! We're still arguing! I'm not arguing! I'm just very invested!",v7("\155\78\177\69\242\60\138\165\78\178\73\166\56\199\187\73\185\76\190\46\199\191\68\174\69\242\60\148\232\67\181\71\242\60\148\232\64\252\67\179\47\198\232\111\179\84\242\48\142\166\68\253\0\159\52\137\173\1\181\83\242\41\143\173\1\174\69\181\40\139\169\83\252\83\187\39\130\233","\231\200\33\220\32\210\93"),"The Cambrian explosion wasn't an explosion! It was very slow! Slightly disappointing! Still cool though!","T. rex teeth were like bananas! Not the taste! The— nevermind. Bananas.",v7("\120\81\72\226\36\93\77\84\254\119\75\93\84\232\119\93\74\73\248\57\88\24\64\226\37\28\89\6\229\34\82\92\84\232\51\28\89\72\233\119\79\81\94\249\46\17\94\79\251\50\28\85\79\225\59\85\87\72\173\46\89\89\84\254\118\28\106\73\248\48\84\84\95\172\119\117\24\84\226\34\82\92\6\233\56\75\86\6\249\56\28\90\67\173\36\93\94\67\172","\87\60\56\38\141"),"People thought the Stegosaurus had a second brain! It didn't! That rumour got around!",v7("\233\229\11\54\208\173\11\56\197\177\3\32\197\161\74\55\217\229\12\53\211\182\3\54\128\166\5\54\204\160\9\46\201\170\4\123\128\145\2\63\206\229\35\122\198\170\31\52\196\229\11\122\206\160\29\122\198\170\25\41\201\169\74\59\206\161\74\40\213\172\4\63\196\229\30\50\197\229\29\50\207\169\15\122\211\188\25\46\197\168\75","\90\160\197\106"),"I've been cleaning this fossil for three days! It's not even my fossil! It's a practice fossil!",v7("\199\188\46\54\91\236\160\106\125\76\236\162\106\116\75\241\177\57\54\67\241\176\106\98\71\224\189\36\127\65\226\185\38\111\2\231\188\36\121\81\226\160\56\101\29\163\129\47\117\74\237\188\41\119\78\239\172\107\54\107\163\166\43\111\2\234\161\106\119\2\239\186\62\55\2\208\186\56\100\91\162","\34\131\213\74\22"),"I know way too much about extinction! It's a conversation killer! Literally! Haha.","I have a favourite dinosaur but it changes! Every week! Currently it's a secret!",v7("\7\244\1\56\49\173\73\112\31\177\90\112\62\182\2\56\57\183\17\126\112\144\86\39\49\170\86\58\37\170\2\112\36\177\31\62\59\176\24\55\112\184\20\63\37\173\86\36\56\188\86\19\34\188\2\49\51\188\25\37\35\247\86\30\63\171\27\49\60\249\2\56\57\183\17\35\113","\80\80\217\118"),"This is going well! I think! I don't have data! But I feel it!",v7("\42\71\4\60\69\105\75\112\4\75\3\116\11\77\74\61\44\8\7\114\19\77\75\112\4\75\3\116\11\77\24\60\69\127\14\113\9\4\75\84\69\68\4\107\0\8\13\116\11\65\24\117\12\70\12\61\17\64\14\112\68","\29\101\40\107"),"If a twisted shows up, shout! I'll come running! I'll try to run fast!",v7("\230\253\213\176\22\133\236\223\166\15\133\230\196\178\16\204\251\209\242\93\236\181\199\188\15\215\236\144\178\31\202\224\196\243\20\209\180\144\154\93\210\250\194\161\4\133\244\210\188\8\209\181\221\186\19\192\181\196\188\18\137\181\216\188\19\192\230\196\191\4\139","\125\165\149\176\211"),"Stamina is not my strongest stat! I know that! I've read my own numbers!","My ability boosts extraction by seventy-five percent for fifteen seconds! I'm telling you in case you— need it!",v7("\96\67\34\224\147\76\67\57\238\197\68\2\36\248\197\90\15\35\229\128\90\67\56\228\132\77\26\107\161\171\70\1\37\229\156\9\11\43\242\197\76\21\47\243\197\72\16\33\228\129\9\23\37\161\150\76\6\106\245\141\76\67\57\237\140\77\6\57\175","\229\41\99\74\129"),"I'm not scared, I'm just— aware! Highly aware! Of the hallway!",v7("\22\19\228\57\42\69\231\39\60\10\243\107\58\22\161\41\50\22\232\40\50\9\237\50\115\4\161\47\58\2\161\56\58\17\228\106\115\32\236\59\39\28\173\107\55\16\242\63\42\73\161\36\48\6\224\56\58\10\239\42\63\9\248\107\55\4\239\44\54\23\238\62\32\68\161\1\38\22\245\107\63\12\234\46\115\1\232\44\32\68","\75\83\101\129"),"Pterosaurs are not dinosaurs! I will not elaborate! Okay, I'll elaborate later!",v7("\219\11\82\213\229\78\69\144\230\67\72\195\178\91\64\196\241\67\1\221\235\88\68\220\244\10\1\228\250\89\68\213\178\74\85\196\247\70\81\196\225\10\1\228\250\78\1\196\250\66\83\212\178\68\79\213\178\67\68\220\246\10","\176\146\43\33"),"I'm learning to sew! From a friend! It's going! It's going okay!","Nobody's listening and that's— fine! Totally fine! I'll just keep talking!",v7("\140\210\177\8\161\110\232\216\231\20\188\59\174\216\244\29\238\114\166\203\248\2\167\121\164\216\174\81\128\116\247\157\222\26\175\98\233\157\214\3\171\122\188\156\177\63\161\105\165\220\253\80","\27\200\189\145\113\206"),v7("\137\203\85\174\91\224\159\90\170\91\224\138\18\167\64\180\197\28\229\15\168\138\90\170\71\161\197\28\229","\47\192\235\50\203"),"Nevermind— it was never fun anyway! Kidding! Mostly!","If I go quiet, I'm counting exits. Two of them. Probably three.","Small steps! Big machine! That's the entire trick!","You're doing great! I mean it! I analyzed nothing but I mean it!",v7("\9\135\18\208\250\217\244\136\96\211\18\212\227\206\173\201\52\207\27\197\172\217\162\140\50\222\14\217\229\210\179\201\40\194\8\212\172\213\167\201\33\135\24\216\248\156\187\159\37\213\25\222\227\215\177\141\97\135\41\193\229\206\189\157\53\198\22\221\245\157","\233\64\167\122\177\140\188\212"),"There's dust on my shell! From the dig site! The digging is imaginary!",v7("\102\52\226\82\226\172\224\74\112\182\79\229\252\254\64\96\254\73\229\187\177\15\93\226\0\227\189\224\95\113\248\83\170\252\221\64\98\255\78\236\252\255\65\53","\144\47\20\150\32\139\220"),"I'm behind you! In a support way! Not a creepy way!","Two hands on the machine! Metaphorically! I'm not making it weird!","I could talk about the Mesozoic for an hour! I'll spare you! This time!","If you're bored, I can be boring quieter! I have that setting!","I brought a spare patch kit! It's never useful! It's never not useful!","It's quiet! I like quiet! I'm going to keep talking over it!",v7("\25\98\170\235\213\148\225\112\38\178\238\212\192\229\112\36\188\250\206\192\229\62\38\253\237\210\133\234\112\46\178\234\206\192\240\56\39\253\233\219\144\225\34\99\253\213\213\147\240\112\54\178\185\210\137\247\36\45\175\224\155\192\208\34\35\186\240\217\193","\132\80\66\221\153\186\224"),v7("\105\167\101\87\136\73\189\54\14\250\6\134\100\0\186\85\239\41\30\183\67\188\100\22\172\71\182\101\87\146\72\239\48\31\190\6\140\54\18\175\71\172\33\24\174\85\238\100\58\190\72\187\37\27\183\95\238","\219\38\207\68\119"),"Are we doing well? I think we're doing well! No data! But yes!","I'd rather dig than fight! Honestly I'd rather neither!","Nobody picks me first! That's fine! It's fine. It's— it's fine.","I'm a mollusk, technically! With hobbies! With a patch kit!","A brachiosaurus neck is longer than— a lot of things! That's a fact!","I keep thinking someone's about to say my name! Awkward!"},[v7("\37\51\43\3\33\179\33\57\57\5","\236\109\118\106\81\117")]={"Oh no— are you alright? Answer honestly! I'll wait right here!","Please, please, please don't panic! I know that's not how panic works! Please anyway!","Okay! New plan! Slower! Smaller steps! I'll stop saying calm!","That was one heart! That's— that's a lot! Come stand over here with me!","Please don't cry! I know you're not crying! I'm preemptively saying it!","I should have said something sooner! I'm sorry! I noticed the corner!","Ouch! New plan! The old plan was bad! I'm sorry, old plan!","Careful! One more of those is not a joke! I'm not joking around about it!",v7("\207\33\195\46\186\229\54\134\41\167\255\32\210\110\238\192\50\197\39\167\227\54\134\35\175\249\54\212\110\238\207\33\195\46\186\229\58\200\40\238\228\32\134\59\166\232\115\214\61\167\226\33\207\59\183\173\53\195\46\186\248\33\195\110","\206\141\83\166\79"),v7("\196\233\219\207\242\249\233\201\194\255\249\233\219\216\241\224\233\210\220\251\255\233\213\207\236\232\232\157\235\236\232\233\196\197\235\173\166\214\203\231\178\233\228\197\235\173\170\220\196\190\254\168\196\138\240\226\232","\158\141\201\189\170"),"Don't worry about looking scared! I look scared constantly! It's fine!","That's the floor being unfair, not you! I have evidence! My feelings!","You need to run? Run! Nobody's judging! I'm certainly not!","I'm hovering! This is a hovering! It's supportive!","New deal! I go in front for a little bit! I'll be brave in bursts!","Half a heart left! I'm going to worry loudly! Just ignore it!","I'm recalculating! Hold on! ...Recalculated! Stay near me!","Hahaha— that was scary! I'm fine! Are you fine? Please be fine!"},[v7("\37\145\203\158\114\62\132\220\150","\45\119\208\153\219")]={"OH! A medkit! Grab it! That's such a good find!","Bandage! Put it somewhere safe! Actually— use it if you need it! Both!","Good pickup! That's heart insurance! That's a real term! Probably!","One of those! I always get excited about those! Sorry! I'm not sorry!","That's worth more than most things on this floor! I have a ranking!","Keep that on you! I mean it! I'll ask about it later!","Rare find! That's— that's lucky! Don't waste it on me though!","I'd have walked right past that! I do that constantly!","Finally! Medical supplies! I've been mentally preparing for this!",v7("\224\81\165\1\83\215\86\177\25\23\148\91\161\85\7\220\92\228\17\26\210\95\161\7\22\218\90\161\84\83\231\86\228\5\31\209\88\183\16\82\148\122\165\7\22\210\76\168\25\10\149","\115\180\57\196\117")},[v7("\27\72\117\217","\160\82\28\48\148\48\164\74")]={"Ooo! Loot! That's— that's the technical term!",v7("\240\223\176\35\46\5\202\222\186\102\41\5\202\222\164\103\122\42\209\209\191\102\51\25\130\144\141\52\59\14\215\217\190\35\122\30\194\214\184\102\61\31\194\210\191\47\52\10\130","\109\163\176\221\70\90"),"A trinket! Or a thing! I don't know the taxonomy of everything!","Every item helps! Every single one! That's not a fact but it sounds right!",v7("\251\82\119\64\123\51\198\1\34\71\118\52\199\77\104\20\90\38\146\77\56\91\120\33\146\84\36\81\117\39\222\0\119\113\101\55\192\88\35\92\122\60\213\1\59\91\124\57\193\1\34\71\118\52\199\77\119\64\124\114\223\68\118","\82\178\33\87\52\19"),"I'll hold it if your hands are full! Metaphorically! Not physically!","Nice find! I'd clap but I'm using my hands for moral support!","Ooh, that one! Yes! That! I don't know what it does! But yes!","Into the bag! Into the— the slots! Whatever they're called!","That's more useful than my facts! Slightly more useful! Okay, a lot!"},[v7("\109\128\193\86\85\120\155","\28\44\194\136\26")]={"Let's do this!",v7("\69\118\82\70\117\139\85\142\120\118\7\18\126\131\72\143\60\80\7\11\115\139\85\142\117\109\6","\174\28\25\39\102\22\234\59"),"I'm here for you! Right here! Physically here!","Teamwork make the dream work! Wait— says teamwork make the dream work! I said it wrong! Moving on!","Inspiration! That's my whole thing! Seventy-five percent for fifteen seconds! Go!",v7("\239\72\3\204\203\148\137\71\31\207\143\198\239\64\